execution.script:
pipeline {
    agent any

    tools {
        // Matches your configured Jenkins JDK name perfectly
        jdk 'JDK21.0.11' 
    }

    stages {
        stage('Build') {
            steps {
                echo 'Pulling code from Git repository...'
                // Using your specific repository and its default 'master' branch
                git branch: 'master', url: 'https://github.com/jglick/simple-maven-project-with-tests.git'

                echo 'Building and packaging...'
                withMaven(maven: 'Maven3') { 
                    sh 'mvn clean package'
                }
            }
        }

        stage('Test') {
            steps {
                echo 'Running unit tests...'
                withMaven(maven: 'Maven3') {
                    sh 'mvn test'
                }
            }
        }

        stage('Deploy') {
            steps {
                echo 'Deploying application...'
                // Note: Make sure your target server and SSH configurations are set up for this step!
                sh 'scp target/*.jar user@server:/deployments/'
            }
        }
    }
}
